def digest(path: Path) -> str:
    return sha256(path.read_bytes()).hexdigest()


def write_complete(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source.lstrip(), encoding="utf-8", newline="\n")
    ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    print(f"[OK] FULL REPLACEMENT: {path.resolve()}")


def main() -> int:
    print("========================================")
    print(" INT-OII-010 INSTALLER")
    print(" AUTHORIZATION CONSUMPTION GATE")
    print("========================================")

    if not (ROOT / "qseries_v2").is_dir():
        raise SystemExit("[ERROR] Run from the kalshi-qss-bot repository root.")
    if not UPSTREAM.is_file():
        raise SystemExit(f"[ERROR] Actual INT-OII-009 module missing: {UPSTREAM}")

    source = UPSTREAM.read_text(encoding="utf-8")
    required = (
        'ENGINE_ID = "INT-OII-009"',
        "OracleCertifiedIntelligenceReadOnlyConsumptionSessionAuthorization",
        "verify_oracle_certified_intelligence_read_only_consumption_session_authorization",
        "authorization_id",
        "authorization_hash",
        "authorization_single_use",
        "authorization_consumed",
        "read_only",
    )
    missing = [token for token in required if token not in source]
    if missing:
        raise SystemExit("[ERROR] INT-OII-009 contract mismatch: " + ", ".join(missing))

    ast.parse(source, filename=str(UPSTREAM))
    upstream_hash = digest(UPSTREAM)
    print("[OK] Actual INT-OII-009 authorization contract verified")

    write_complete(PRODUCTION, PRODUCTION_SOURCE)
    write_complete(TEST, TEST_SOURCE)

    export_line = "from .oracle_certified_intelligence_read_only_consumption_session_authorization_consumption_gate import *"
    existing = PACKAGE_INIT.read_text(encoding="utf-8") if PACKAGE_INIT.exists() else ""
    if export_line not in existing.splitlines():
        if existing and not existing.endswith("\n"):
            existing += "\n"
        PACKAGE_INIT.write_text(existing + export_line + "\n", encoding="utf-8", newline="\n")
        ast.parse(PACKAGE_INIT.read_text(encoding="utf-8"), filename=str(PACKAGE_INIT))
        print(f"[OK] PACKAGE UPDATED: {PACKAGE_INIT.resolve()}")
    else:
        print(f"[OK] PACKAGE EXPORT PRESENT: {PACKAGE_INIT.resolve()}")

    if digest(UPSTREAM) != upstream_hash:
        raise RuntimeError("Protected INT-OII-009 module changed during installation")

    completed = subprocess.run([sys.executable, str(TEST)], cwd=str(ROOT), check=False)
    if completed.returncode:
        raise SystemExit(completed.returncode)

    if digest(UPSTREAM) != upstream_hash:
        raise RuntimeError("Protected INT-OII-009 module changed during testing")

    print("[PASS] Protected INT-OII-009 module unchanged")
    print("[PASS] INT-OII-001 through INT-OII-009 lineage preserved")
    print("[PASS] No acquisition, analytics, Operator, or Q Series execution module modified")
    print("[DONE] INT-OII-010 AUTHORIZATION CONSUMPTION GATE INSTALLED")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
